#pragma once
// WiiDS: rebuilds the game executable's loaded image from the player's own disc at startup.
//
// Release builds carry no Nintendo executable bytes. Each section the translated code expects in
// guest memory (the DOL sections, and the linked REL image) is rebuilt from the extracted disc
// under [paths] dvd_root, exactly as the build-time tools produced it, then checked against a
// pinned SHA-256 before it is copied in. The manifest (data_sections_runtime.cpp, generated by
// experiments/release/gen_game_data_manifest.py) holds only names, addresses, sizes and hashes.
// Shared verbatim between the DriftDroid and NSMB Wii runtimes.
#include <cstddef>
#include <cstdint>

namespace WiiDSGameData {

enum class Source : uint8_t {
    DolSection,      // sys/main.dol section loaded at `address`
    StaticRel,       // files/rel/StaticR.rel linked at `address` (Mario Kart Wii)
    NsmbwLinkedRels, // files/rels/*.rel.LZ decompressed and pre-linked into one image (NSMB Wii)
};

enum class Patch : uint8_t {
    None,
    Msmbwii, // MSMBWii: Another SMBW System table words from the player's mod files
};

struct Section {
    const char* name;
    uint32_t address;
    uint32_t size;
    const char* sha256;
    Source source;
};

struct Game {
    const char* title;     // shown to the player, e.g. "Mario Kart Wii"
    const char* disc;      // the exact disc it needs, e.g. "Europe (PAL), RMCP01, revision 0"
    Patch patch;
};

// Never returns on failure: shows a fatal popup that names the disc the game needs.
void Load(const Game& game, const Section* sections, size_t count);

} // namespace WiiDSGameData
